<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>DVD Bounce</title>
    <style>
        body {
            margin: 0;
            padding: 0;
            overflow: hidden;
            background-color: black;
        }
        #dvd {
            position: absolute;
            font-family: sans-serif;
            font-weight: bold;
            font-size: 40px;
            white-space: nowrap;
            color: white;
        }
    </style>
</head>
<body>

    <div id="dvd">DVD</div>

    <script>
        const dvd = document.getElementById('dvd');
        let x = Math.random() * (window.innerWidth - 100);
        let y = Math.random() * (window.innerHeight - 50);
        let xSpeed = 3;
        let ySpeed = 3;

        function animate() {
            x += xSpeed;
            y += ySpeed;

            // Collision detection for right and left walls
            if (x + dvd.offsetWidth > window.innerWidth || x < 0) {
                xSpeed *= -1;
            }

            // Collision detection for top and bottom walls
            if (y + dvd.offsetHeight > window.innerHeight || y < 0) {
                ySpeed *= -1;
            }

            dvd.style.left = x + 'px';
            dvd.style.top = y + 'px';

            requestAnimationFrame(animate);
        }

        animate();

        // Adjust position if window is resized
        window.addEventListener('resize', () => {
            x = Math.min(x, window.innerWidth - dvd.offsetWidth);
            y = Math.min(y, window.innerHeight - dvd.offsetHeight);
        });
    </script>
</body>
</html>
